@dataclass(frozen=True)
class Customer:
    id: int
    name: str

    @classmethod
    def from_row(cls, row: sqlite3.Row) -> "Customer":
        return cls(id=row["id"], name=row["name"])

def load_customer(conn: sqlite3.Connection, cid: int) -> Customer | None:
    row = conn.execute("SELECT id, name FROM customers WHERE id = ?", (cid,)).fetchone()
    return Customer.from_row(row) if row else None
